mapper.select:
SELECT
    score.*
FROM scc_npm_sou_expert_score score
WHERE 1 = 1

    AND score.SOU_NAME LIKE concat('%', concat(#{souName}, '%'))


    AND exists (
        SELECT line.EXPERT_SCORE_ID FROM scc_npm_sou_expert_score_line line
        WHERE line.EXPERT_SCORE_ID = score.EXPERT_SCORE_ID AND line.GROUP_TYPE = 'SOU_LEADER' AND line.USERNAME = #{leaderUserName}
    )


    AND exists (
    SELECT line.EXPERT_SCORE_ID FROM scc_npm_sou_expert_score_line line
    WHERE line.EXPERT_SCORE_ID = score.EXPERT_SCORE_ID AND line.GROUP_TYPE = 'SOU_MANAGER' AND line.USERNAME = #{managerUserName}
    )


    AND score.PROJECT_ADDRESS LIKE concat('%', concat(#{projectAddress}, '%'))


    AND score.SCORE_TIME >= #{scoreTimeFrom}


    AND score.SCORE_TIME <= #{scoreTimeTo}
